mapper.select:
select gwpgd.price
from gc_wholesale_price_group_detail gwpgd
left join csr_client_wholesale_config ccwc on gwpgd.price_group_code = ccwc.price_group_code and ccwc.biz_org_code = #{bizOrgCode,jdbcType=VARCHAR}
where gwpgd.price_group_code = #{priceGroupCode,jdbcType=VARCHAR} and gwpgd.goods_code = #{goodsCode,jdbcType=VARCHAR}
and gwpgd.biz_org_code = #{bizOrgCode,jdbcType=VARCHAR} and  ccwc.client_code = #{clientCode,jdbcType=VARCHAR} and gwpgd.is_delete = 0
